import secrets
from flask import session, render_template_string

def install(application):
    import cms
    from app import can_edit
    cms.CLIENT = cms.CLIENT.replace('document.head.append(css)', 'document.head.append(css);window.inlineSettings=d;window.dispatchEvent(new Event("inline-settings-ready"))')
    original = application.view_functions['home']
    def home():
        page = original()
        if not can_edit():
            return page
        tools = render_template_string(TOOLS, csrf=session.setdefault('csrf', secrets.token_urlsafe(32)), uid=session['uid'])
        return page.replace('</body>', tools + '</body>')
    application.view_functions['home'] = home

TOOLS = '''<style>#inline-toolbar{position:fixed;bottom:12px;left:3%;right:3%;z-index:999;background:#fffaf8;border:2px solid #b76a8b;border-radius:16px;box-shadow:0 4px 25px #34564e33;padding:12px 16px;color:#34564e;font:13px/1.6 Arial}#inline-toolbar button,#inline-toolbar a{display:inline-block;margin:4px;padding:8px 12px;border:1px solid #9b6b80;border-radius:9px;background:#ffe0ed;color:#623448;font:inherit;cursor:pointer}#inline-toolbar button:disabled{opacity:.5;cursor:default}body{padding-bottom:190px}.inline-editable{white-space:pre-wrap;overflow-wrap:anywhere}body.inline-editing .inline-editable{outline:2px dashed #bc638a;outline-offset:4px;cursor:text;min-width:10px;min-height:1em}body.inline-editing .inline-editable:focus{outline:3px solid #9b426d;background:#fff0f7}#inline-status{margin:4px 0 0}#inline-toolbar [hidden]{display:none!important}</style><section id="inline-toolbar" aria-label="Homepage editor"><div><strong>Homepage editor</strong> · <span id="inline-mode">Preview mode</span> · <span id="inline-dirty">No unsaved edits</span></div><button id="inline-toggle" disabled aria-pressed="false">Edit text</button><button id="inline-save" disabled>Save for everyone</button><button id="inline-draft" disabled>Save local draft</button><button id="inline-restore" disabled>Restore local draft</button><button id="inline-cancel" disabled>Discard edits</button><a href="/editor">Colors & settings</a><a href="/editor/artwork">Crop artwork</a><p id="inline-status" role="status" aria-live="polite">Loading saved page settings…</p></section><script>(()=>{
const $=id=>document.getElementById('inline-'+id),token={{ csrf|tojson }},draftKey='luka-inline-draft:'+{{ uid|tojson }};
let baseline=null,fields={},editing=false,busy=false,dirty=false;
const map={site_name:'header a[href="#"]',badge:'.pill',headline_top:'#inline-headline-top',headline_bottom:'.hero h1 span:last-child',subtitle:'.subtitle',description:'.description',caption:'.caption',ribbon:'.ribbon',community_heading:'.community h2',join_top:'.hero .btn.pink',join_bottom:'.community .btn.pink',navigation:'a[href="#community"]',nav_discord:'header a[target]',copy_text:'#copy',placeholder:'.placeholder p',footer:'footer'};
const say=text=>$('status').textContent=text;
function text(){return Object.fromEntries(Object.entries(fields).map(([key,el])=>[key,el.innerText.replace(/\r\n/g,'\n')]))}
function apply(data){for(const [key,el]of Object.entries(fields))el.textContent=data[key]}
function refresh(){if(!baseline)return;const values=text();dirty=Object.keys(fields).some(k=>values[k]!==baseline[k]);$('dirty').textContent=dirty?'Unsaved edits':'No unsaved edits';$('save').disabled=busy||!dirty;$('cancel').disabled=busy||!dirty;$('draft').disabled=busy;$('restore').disabled=busy;$('toggle').disabled=busy}
function mode(value){editing=value;document.body.classList.toggle('inline-editing',value);for(const [key,el]of Object.entries(fields)){el.contentEditable=value?'true':'false';el.spellcheck=value;if(value){el.setAttribute('role','textbox');el.setAttribute('aria-label','Edit '+key.replaceAll('_',' '));el.setAttribute('aria-multiline','true');el.tabIndex=0}else{el.removeAttribute('role');el.removeAttribute('aria-label');el.removeAttribute('aria-multiline');el.removeAttribute('tabindex')}}$('mode').textContent=value?'Edit mode':'Preview mode';$('toggle').textContent=value?'Preview page':'Edit text';$('toggle').setAttribute('aria-pressed',String(value));refresh()}
function validate(values){return Object.keys(fields).every(k=>typeof values[k]==='string'&&values[k].length<=(['description','footer'].includes(k)?4000:400))}
function ready(){if(baseline||!window.inlineSettings)return;baseline={...window.inlineSettings};const h=document.querySelector('.hero h1');if(h&&h.firstChild&&h.firstChild.nodeType===Node.TEXT_NODE){const top=document.createElement('span');top.id='inline-headline-top';top.style.color='inherit';top.textContent=h.firstChild.textContent;h.replaceChild(top,h.firstChild)}for(const [key,selector]of Object.entries(map)){const el=document.querySelector(selector);if(el){fields[key]=el;el.classList.add('inline-editable');el.addEventListener('input',refresh);el.addEventListener('paste',e=>{if(!editing)return;e.preventDefault();const s=window.getSelection();if(!s||!s.rangeCount)return;const range=s.getRangeAt(0);if(!el.contains(range.commonAncestorContainer))return;range.deleteContents();const t=document.createTextNode((e.clipboardData?.getData('text/plain')||'').slice(0,4000));range.insertNode(t);range.setStartAfter(t);range.collapse(true);s.removeAllRanges();s.addRange(range);refresh()});el.addEventListener('drop',e=>{if(editing)e.preventDefault()})}}apply(baseline);mode(false);say('Click Edit text, then click an outlined area to type. Local drafts stay in this browser; Save for everyone publishes. If two admins edit at once, the last save wins.')}
window.addEventListener('inline-settings-ready',ready);ready();setTimeout(()=>{if(!baseline)say('Page settings did not load. Reload before editing; no changes have been saved.')},20000);
$('toggle').onclick=()=>{if(!busy&&baseline){mode(!editing);say(editing?'Click any outlined text to type. Links are disabled while editing.':'Preview mode. Unsaved edits remain visible until saved or discarded.')}};
$('cancel').onclick=()=>{if(busy||!baseline)return;if(dirty&&!confirm('Discard edits and restore the page text loaded at your last save?'))return;apply(baseline);mode(false);say('Edits discarded. Your local draft, if any, was not deleted.')};
$('draft').onclick=()=>{const values=text();if(!validate(values)){say('Text is too long. Use at most 400 characters per field, or 4,000 for description and footer.');return}try{localStorage.setItem(draftKey,JSON.stringify({version:1,text:values}));say('Draft saved in this browser only. It has not been published.')}catch(e){say('Local storage is unavailable or full. Draft was not saved.')}};
$('restore').onclick=()=>{try{const raw=localStorage.getItem(draftKey);if(!raw){say('No local draft was found in this browser.');return}const data=JSON.parse(raw);if(data.version!==1||!data.text||!validate(data.text))throw new Error('Invalid draft');if(dirty&&!confirm('Replace your current unsaved edits with your local draft?'))return;apply(data.text);mode(true);say('Local draft restored for review. Press Save for everyone to publish it.')}catch(e){say('Could not read a valid local draft. Current edits were not changed.')}};
$('save').onclick=async()=>{if(busy||!baseline)return;const values=text();if(!validate(values)){say('Text is too long. Use at most 400 characters per field, or 4,000 for description and footer.');return}const payload={...baseline,...values};busy=true;for(const el of Object.values(fields))el.contentEditable='false';refresh();say('Publishing changes…');try{const r=await fetch('/api/page-settings',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':token},body:JSON.stringify(payload)});let d;try{d=await r.json()}catch(e){throw new Error('Unexpected response. Check that you are still signed in.')}if(!r.ok)throw new Error(d.error||'Publishing failed.');baseline=payload;window.inlineSettings=payload;busy=false;apply(baseline);mode(false);say('Saved for everyone! Visitors will see the changes when they reload.')}catch(e){busy=false;mode(editing);say(e.message+' Your edits remain on this page.')}};
document.addEventListener('click',e=>{if(editing&&e.target.closest('.inline-editable')&&e.target.closest('a,button')){e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&baseline){e.preventDefault();if(!busy)$('draft').click()}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
})();</script>'''
